package com.bank.decompose.client;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Replaces the old in-DB join. Payment now CALLS the account owner.
public class AccountServiceClient {
    private static final Logger log = Logger.getLogger(AccountServiceClient.class.getName());
    private boolean down = false;
    public void simulateOutage(boolean down) { this.down = down; }

    public void debit(String accountId, BigDecimal amount) {
        if (down) throw new RuntimeException("Account Service unavailable");
        log.info(() -> "REMOTE debit " + amount + " from " + accountId);
    }
    public void credit(String accountId, BigDecimal amount) {
        log.info(() -> "REMOTE compensating credit " + amount + " to " + accountId);
    }
}
