package com.bank.decompose.payment;

import com.bank.decompose.client.AccountServiceClient;
import java.math.BigDecimal;
import java.util.logging.Level;
import java.util.logging.Logger;

// Extracted Payment Service: owns payments data, uses a SAGA across the boundary.
public class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());
    private final AccountServiceClient accountClient;

    public PaymentService(AccountServiceClient accountClient) { this.accountClient = accountClient; }

    public String makePayment(String fromAccount, BigDecimal amount) {
        try {
            accountClient.debit(fromAccount, amount);         // step 1 (remote)
            log.info(() -> "Payment recorded in Payment Service DB");
            return "COMPLETED";
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "Debit failed — no local record written", ex);
            return "FAILED";
        }
    }
}
