package com.bank.decompose.strangler;

import com.bank.decompose.monolith.MonolithApp;
import com.bank.decompose.payment.PaymentService;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Strangler Fig: route payments to the NEW service, everything else to the monolith.
public class StranglerFacade {
    private static final Logger log = Logger.getLogger(StranglerFacade.class.getName());
    private final PaymentService paymentService;
    private final MonolithApp monolith;

    public StranglerFacade(PaymentService paymentService, MonolithApp monolith) {
        this.paymentService = paymentService;
        this.monolith = monolith;
    }

    public String route(String path, String accountId, BigDecimal amount) {
        if (path.startsWith("/payments")) {
            log.info("Routing " + path + " → EXTRACTED Payment Service");
            return paymentService.makePayment(accountId, amount);
        }
        log.info("Routing " + path + " → legacy monolith");
        return monolith.accountLookup(accountId);
    }
}
