package com.bank.decompose;

import com.bank.decompose.client.AccountServiceClient;
import com.bank.decompose.monolith.MonolithApp;
import com.bank.decompose.payment.PaymentService;
import com.bank.decompose.strangler.StranglerFacade;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class DecomposeDemo {
    private static final Logger log = Logger.getLogger(DecomposeDemo.class.getName());

    public static void main(String[] args) {
        AccountServiceClient accountClient = new AccountServiceClient();
        PaymentService paymentService = new PaymentService(accountClient);
        MonolithApp monolith = new MonolithApp();
        StranglerFacade facade = new StranglerFacade(paymentService, monolith);
        BigDecimal rentAmount = new BigDecimal("50000");

        log.info("=== Payment routed to extracted service ===");
        log.info("Result: " + facade.route("/payments", "SAV2001", rentAmount));

        log.info("=== Account lookup still served by monolith ===");
        log.info("Holder: " + facade.route("/accounts", "SAV2001", null));

        log.info("=== Account Service down: saga sees failure ===");
        accountClient.simulateOutage(true);
        log.info("Result: " + facade.route("/payments", "SAV2001", rentAmount));
    }
}
